"""Build classified bilingual Markdown from reviewed question extracts and verified results."""
from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[1]
Q=json.loads((ROOT/'sources/questions.json').read_text())
R=json.loads((Path(__file__).with_name('verified_results.json')).read_text())
def norm(s):
 s=s.replace('’',"'").replace('‘',"'")
 for a,z in [("passage à l échelle", "passage à l'échelle"),("Ajout d un", "Ajout d'un"),("Variante de l examen", "Variante de l'examen"),("Uniformité d un", "Uniformité d'un")]:s=s.replace(a,z)
 for a,z in [('TD3_2627_ex1_duplicated_fr.png','td3_duplicated.png'),('TD3_2627_ex2_partI_network.png','td3_identical.png'),('TD3_2627_ex2_partII_network.png','td3_heterogeneous.png')]:s=s.replace('../../TD/Images/'+a,'sources/'+z)
 return s

def b(f,z):return norm(f+' '+z)+'\n\n'
def table(headers,rows):return '| '+' | '.join(headers)+' |\n|'+ '|'.join(['---']*len(headers))+'|\n'+''.join('| '+' | '.join(str(x) for x in row)+' |\n' for row in rows)+'\n'
def eq(s):return '\n$$\n'+s+'\n$$\n\n'
def merge(key):
 v=Q[key]
 if isinstance(v,str):s=v
 else:
  f,z=v;fb=re.split(r'\n\s*\n',f);zb=re.split(r'\n\s*\n',z)
  if key=='td1_2.2':zb=[' '.join(zb[:3])]+zb[3:]
  assert len(fb)==len(zb),(key,len(fb),len(zb));blocks=[]
  for ff,zz in zip(fb,zb):
   if ff.startswith(('$$','```')):blocks.append(ff);continue
   fl=ff.splitlines();zl=zz.splitlines()
   if ff.startswith('|'):
    assert len(fl)==len(zl),(key,ff,zz);ls=[]
    for a,c in zip(fl,zl):
     if re.match(r'^\|[\s:|\-]+$',a):ls.append(a);continue
     ac=a.strip('|').split('|');cc=c.strip('|').split('|');assert len(ac)==len(cc)
     ls.append('| '+' | '.join(x.strip() if x.strip()==y.strip() else x.strip()+' '+y.strip() for x,y in zip(ac,cc))+' |')
    blocks.append('\n'.join(ls));continue
   if ff.startswith('!['):
    blocks.append(ff.replace(re.search(r'!\[(.*?)\]',ff).group(1),re.search(r'!\[(.*?)\]',ff).group(1)+' '+re.search(r'!\[(.*?)\]',zz).group(1),1));continue
   if len(fl)==len(zl):
    ls=[]
    for a,c in zip(fl,zl):
     pat=r'^(#+ |\s*\d+\. |\s*- |\*\*\([a-z]\)\*\* )';am=re.match(pat,a);cm=re.match(pat,c)
     if am and cm:
      lead=am.group();ls.append(lead+a[len(lead):]+' '+c[len(cm.group()):])
     else:ls.append(a+' '+c)
    blocks.append('\n'.join(ls))
   else:blocks.append(' '.join(fl)+' '+' '.join(zl))
  s='\n\n'.join(blocks)
 s=re.sub(r'^\*Figure 1.*$', '', s, flags=re.M)
 s=re.sub(r'^#{3,5} ', '#### ',s,flags=re.M)
 s=s.replace('(Images/', '(../../TD/Images/')
 # Remove old local links to standalone TD4 calculators/tables; references below are self-contained.
 s=s.replace('(td4_calculs.py)','(sources/calculations.py)')
 return norm(s)+'\n\n'
exercise_manifest=[]
pending_items=[]
def item(title,key,source,answer):
 pending_items.append(dict(key=key,title=norm(title),source=source))
 return ('\\newpage\n\n' if key=='exam2023_2' else '')+'## '+title+'\n\n'+b('Source : '+source,'来源：'+source)+'### Énoncé 题目\n\n'+merge(key)+'### Corrigé détaillé 逐步解答\n\n'+answer
common=b('Corrigés de travail vérifiés, distincts d\'un corrigé officiel. Les hypothèses utiles sont précisées avec chaque solution.','本资料为经计算核对的学习题解，不是教师标准答案。各题解答中写明所用假设。')
docs=[]
def document(stem,title,intro,body):
 for x in pending_items:x['stem']=stem;exercise_manifest.append(x)
 pending_items.clear()
 text='# '+title+'\n\n'+intro+common+body
 text=norm(text).replace("passage à l échelle", "passage à l'échelle").replace("Ajout d un", "Ajout d'un").replace("Variante de l examen", "Variante de l'examen");title=norm(title).replace("passage à l échelle", "passage à l'échelle");(ROOT/(stem+'.md')).write_text(text);docs.append((stem,title))
# 01
intro=b('Reconnaître le modèle : taille fixe pour Amdahl, problème agrandi pour Gustafson, amélioration partielle pour la vectorisation.','先识别模型：固定规模用 Amdahl，扩大规模用 Gustafson，局部加速用向量化模型。')
method='## Méthode commune 通用方法\n\n'+eq(r'S(P)=\frac{T_1}{T_P},\quad E=\frac SP,\quad S_A=\frac1{s+(1-s)/P},\quad S_G=P-(P-1)s_p.')+b('Dans Amdahl, s est mesuré sur le temps séquentiel ; dans Gustafson, $s_p$ est mesuré sur le temps parallèle.','Amdahl 的串行比例以串行运行时间为基准，Gustafson 的比例以并行运行时间为基准。')
a=b('Le temps relatif vaut $0.04+0.96/P$. Calculer S puis E pour chaque P.','相对耗时为 $0.04+0.96/P$，先求加速比，再除以处理器数得到效率。')+table(['P','S','E (%)'],[[x['P'],f"{x['S']:.4f}",f"{100*x['E']:.2f}"] for x in R['amdahl']])+eq(r'\lim_{P\to\infty}S(P)=1/0.04=25.')+b('La borne 25 est une limite, non une valeur atteinte à P fini.','25 是上确界，有限处理器数时达不到。')
body=method+item('1 Amdahl avec 4 pour cent séquentiels 串行比例 4%', 'td1_1.1','TD1 §1.1, PDF p.1',a)
a=eq(r's_{\rm eff}(P)=\frac{1/S(P)-1/P}{1-1/P}=\frac{P/S(P)-1}{P-1}.')+table(['P','A : $s_{eff}$ (%)','B : $s_{eff}$ (%)'],[[x['P'],f"{100*x['A']:.4f}",f"{100*x['B']:.4f}"] for x in R['inverse_amdahl']])+b('A reste proche de 5 % : ses mesures sont compatibles avec une fraction effective presque constante. Pour B, elle passe de 3.09 % à 9.93 %, signe de coûts croissants absorbés par le modèle.','A 的有效串行比例约为 5%，与近似固定比例的模型相符；B 从 3.09% 升至 9.93%，表明模型吸收的额外开销随并行规模增大。')+b('A passe mieux à l\'échelle sur les valeurs mesurées. Les temps séquentiels manquent pour classer leurs vitesses absolues ; cette fraction effective ne mesure pas à elle seule le code intrinsèquement séquentiel.','在测得的范围内 A 扩展性更好。缺少两程序各自的串行耗时，尚不能比较绝对速度；有效串行比例也不能单独代表代码固有的串行部分。')
body+=item('2 Inverser Amdahl 反求串行比例','td1_1.2','TD1 §1.2, PDF p.1',a)
a=eq(r'T_P=T_1[s+(1-s)/P],\quad S=\frac{P}{1+(P-1)s}\le P.')+b('(a) À P fixé, le maximum P correspond à s=0, sans surcoût.','(a) 处理器数固定时，无额外开销且 s=0 才达到最大加速比 P。')+eq(r'(b)\quad \lim_{P\to\infty}S=1/s\quad(s>0).')+b('Si s=0, la borne croît avec P.','若 s=0，则理想加速比随 P 增长，没有固定的有限上界。')+eq(r'(c)\quad s=k/n\Longrightarrow S(P,n)=\frac{nP}{n+k(P-1)},\qquad\lim_{n\to\infty}S(P,n)=P.')+b('La proportionnalité inverse impose une constante k ; prendre k=1 est un cas particulier. La limite en n suppose P fixé.','“反比”应写成 $s=k/n$，其中 k 为常数；$k=1$ 只是特例。对 n 取极限时须固定 P。')
body+=item('3 Expression générale 一般表达式','td1_1.3','TD1 §1.3(a–c), PDF p.1',a)
a=b('Supposer des coûts scalaires uniformes par opération, afin que la fraction d\'opérations f soit aussi la fraction du temps scalaire de référence.','假设各操作标量执行成本一致，才可把操作数比例 f 作为标量基准时间比例。')+eq(r'(a)\quad S(f)=\frac1{(1-f)+f/20},\quad 0\le f\le1.')+table(['f (%)','0','20','40','60','70','80','90','100'],[['S','1','1.2346','1.6129','2.3256','2.9851','4.1667','6.8966','20']])+"![Courbe de vectorisation 向量化加速比曲线](../../TD/Images/td1_4_vector_speedup_fr.png)\n\n"+eq(r'(b)\quad f=\frac{1-1/2}{1-1/20}=\frac{10}{19}=52.6316\%.')+eq(r'(c)\quad S_{max}=20,\quad S=10\Longrightarrow f=\frac{18}{19}=94.7368\%.')+eq(r'(d)\quad T_{new}/T_s=0.30+0.70/40=0.3175,\quad S_{new}=3.149606.')+eq(r'1-f^{\prime}+f^{\prime}/20=0.3175\Longrightarrow f^{\prime}=0.718421.')+b('Sans nouveau matériel, porter f de 70 % à 71.8421 %, soit +1.8421 point ; gain global d\'environ 5.51 %.','不购买新硬件时，将向量化比例从 70% 提至 71.8421%，增加 1.8421 个百分点，即可得到同样性能；整体收益约 5.51%。')
body+=item('4 Vectorisation 向量化','td1_1.4','TD1 §1.4(a–d), PDF p.1–2',a)
a=eq(r'1.\quad S_G(8)=8-7\times0.14=7.02.')+eq(r'2.\quad 10-9s\ge7.02\Longrightarrow s\le\frac{2.98}{9}=0.331111\approx33.1111\%.')+b('Ce sont les valeurs du modèle idéal de Gustafson. Le signe « ≤ » de l\'énoncé exprime une borne ; sans hypothèse d\'absence de surcoûts, atteindre cette borne n\'est pas garanti.','以上为 Gustafson 理想模型值。原题的“≤”表示上界；若不假设额外开销可忽略，不能保证实际达到该值。')
body+=item('5 Gustafson Barsis 规模扩展加速比','exam2025_2','TD1 §3.1–3.2, PDF p.4 ; examen 2025 ex.2 Q1–2, p.2',a)
document('01_加速比与向量化','Accélération et vectorisation 加速比与向量化',intro,body)
# 02
intro=b('Calculer des débits en conservant le travail réellement exécuté, puis comparer les durées pour une même tâche.','计算吞吐率时先分清实际执行的工作量；比较同一任务的性能时，以完成时间为依据。')
body='## Formules utiles 常用公式\n\n'+eq(r'T=\frac{N\,CPI}{f},\quad MIPS=\frac{N}{10^6T}=\frac{f}{10^6CPI},\quad MFLOPS=\frac{N_{FLOP}}{10^6T}.')
x=R['whetstone'];a=table(['Configuration 配置','MIPS','N instructions 指令数'],[['Coprocesseur 协处理器',f"{x['MIPS_h']:.6f}",f"{x['N_h']:.0f}"],['Logiciel 软件',f"{x['MIPS_s']:.6f}",f"{x['N_s']:.3f}"]])+b('(a–b) Utiliser la fréquence 16.67 MHz et les CPI 10 et 6 ; les nombres non entiers résultent des mesures arrondies.','(a–b) 使用频率 16.67 MHz，CPI 分别取 10 和 6；由已舍入的测量反推，指令数出现小数属于数值近似。')+eq(r'(c)\quad N_h=I+F,\quad N_s=I+YF\Longrightarrow Y=1+\frac{N_s-N_h}{F}\approx184.993.')+b('Ce calcul suppose que chaque opération flottante correspond à une instruction matérielle et que les instructions entières de fond I restent identiques. On obtient environ 185 instructions d\'émulation par opération.','这一计算假设每个浮点操作对应一条硬件浮点指令，且两配置的背景整数指令 I 相同，得到每次浮点操作约 185 条仿真指令。')+b('Si l\'on compte toutes les instructions logicielles, fond inclus, le rapport $N_s/F=193.1983$ est le coût total moyen par opération. Ces deux périmètres doivent être distingués ; l\'énoncé ne détaille pas le code de fond.','若把软件运行的全部指令都算入，$N_s/F=193.1983$ 是含背景工作的总指令摊销成本。二者统计范围不同；原题没有提供背景代码明细。')+eq(r'(d)\quad MFLOPS=\frac{195578}{1.08\times10^6}=0.181091.')+b('Le coprocesseur est $13.6/1.08=12.5926$ fois plus rapide malgré des MIPS plus faibles.','协处理器的 MIPS 更低，但完成相同任务快 $13.6/1.08=12.5926$ 倍。')
body+=item('1 Whetstone 协处理器与软件仿真','td1_2.1','TD1 §2.1(a–d), PDF p.2–3',a)
a=eq(r'(a)\quad120=\frac{I+YF}{10^6W},\qquad80=\frac{I+F}{10^6B}.')+eq(r'(b)\quad I=120\times10^6\times4-50\times8\times10^6=80\times10^6.')+eq(r'(c)\quad B=\frac{80\times10^6+8\times10^6}{80\times10^6}=1.1\ {\rm s}.')+eq(r'(d)\quad MFLOPS=\frac{8\times10^6}{1.1\times10^6}=7.272727.')+eq(r'(e)\quad S=W/B=4/1.1=3.636364.')+b('L\'achat améliore la vitesse de ce test d\'un facteur 3.6364. La baisse des MIPS vient d\'un nombre bien moindre d\'instructions. Le coût d\'achat manque pour juger la rentabilité financière.','该硬件使此测试快约 3.6364 倍，MIPS 下降源于指令总数大幅减少。题面未给购买成本，因此收益判断限于执行性能。')
body+=item('2 Ajout d un coprocesseur 新增浮点协处理器','td1_2.2','TD1 §2.2(a–e), PDF p.3',a)
x=R['benchmarks'];a=b('Q1. Pour chaque benchmark, $M_{ij}=N_i/(10^6T_{ij})$. Les poids égaux donnent la moyenne arithmétique par benchmark.','第 1 问：先逐项求 $M_{ij}=N_i/(10^6T_{ij})$，等权基准取逐项算术平均。')+table(['Benchmark','Système 1','Système 2','Système 3'],[[i+1,*[f'{v:.4f}' for v in row]] for i,row in enumerate(x['mips'])])+table(['Grandeur 指标','Système 1','Système 2','Système 3'],[['Temps moyen (s) 平均耗时',*[f'{v:.4f}' for v in x['mean_time']]],['MIPS moyens 平均MIPS',*[f'{v:.4f}' for v in x['mean_mips']]],['MIPS du lot 整批吞吐',*[f'{v:.4f}' for v in x['pooled_mips']]]])+b('Les MIPS du lot sont $\\sum N_i/(10^6\\sum T_{ij})$ ; ils ne sont pas la moyenne non pondérée des débits.','整批吞吐率为 $\\sum N_i/(10^6\\sum T_{ij})$，与各基准吞吐率的非加权平均不同。')+b('Q2. Référence système 3 : $a_{ij}=T_{i3}/T_{ij}$.','第 2 问：系统 3 为基准，逐项加速比为 $a_{ij}=T_{i3}/T_{ij}$。')+table(['Benchmark','Système 1','Système 2','Système 3'],[[i+1,*[f'{v:.6f}' for v in row]] for i,row in enumerate(x['speedups'])])+table(['Moyenne 平均口径','Système 1','Système 2','Système 3'],[['Arithmétique 算术',*[f'{v:.6f}' for v in x['arithmetic_speed']]],['Géométrique 几何',*[f'{v:.6f}' for v in x['geometric_speed']]],['Lot complet 整批',*[f'{v:.6f}' for v in x['suite_speed']]]])+b('Une moyenne de ratios doit préciser sa convention. La moyenne géométrique convient à un résumé de rapports normalisés ; le ratio des temps totaux décrit une exécution de chaque benchmark. Les valeurs arithmétiques répondent à une moyenne égale des ratios mais ne donnent pas le speedup du lot.','平均加速比须写清口径。几何平均适合汇总归一化比值；总耗时之比对应每个程序各运行一次；比值算术平均对应比值等权，却不等于整批任务的实际加速比。')+b('Pour ce lot, le classement est système 3, puis 2, puis 1. Le benchmark 2 favorise toutefois le système 1 : le classement n\'est pas universel.','本组任务整体排序为系统 3、系统 2、系统 1，但基准 2 是系统 1 更快，因此不能把汇总排序视为所有应用的普遍排序。')
body+=item('3 Benchmarks et moyennes 基准程序与平均性能','exam2023_2','Examen 2023 ex.2 Q1–2, p.2',a)
document('02_指令吞吐与基准比较','MIPS CPI et benchmarks 指令吞吐与基准比较',intro,body)
# 03
body='## Méthode commune 通用方法\n\n'+eq(r'S=T_1/T_P,\quad E=S/P,\quad e=\frac{1/S-1/P}{1-1/P}=\frac{PT_P/T_1-1}{P-1}.')+b('Calculer e seulement pour P>1. Il absorbe sérialisation et surcoûts observés.','只对 P>1 计算 e；它吸收串行化及观测到的并行开销。')
for k,label,key,src in [('cray','1 Cray Y MP 8','td1_4.1','TD1 §4.1(a–c), PDF p.4'),('alliant','2 Aliant FX 40','td1_4.2','TD1 §4.2(a–b), PDF p.4–5')]:
 a=table(['P','T (s)','S','E (%)','e'],[[v['P'],v['T'],f"{v['S']:.6f}",f"{100*v['E']:.4f}",f"{v['e']:.6f}"] for v in R[k]])
 if k=='cray':a+=b('Les accélérations augmentent, avec efficacité de 97.75 % à 86.94 %. Le facteur e reste proche de 2.1–2.3 % : les mesures sont compatibles avec une fraction effective presque constante.','加速比持续增大，效率从 97.75% 降至 86.94%；e 约为 2.1%–2.3%，与近似固定的有效串行比例相符。')+b('Cela soutient un bon passage à l\'échelle sur la plage mesurée, sans identifier à lui seul la cause des coûts. Une extrapolation idéale donnerait environ 1/0.0214 ≈ 46.7, à condition de conserver ce modèle.','这支持测量范围内扩展良好的判断，但单靠 e 不能定位开销来源。若模型继续成立，理想外推上界约为 $1/0.0214\\approx46.7$。')
 else:a+=b('L\'efficacité diminue de 94.97 % à 80.61 % tandis que e augmente de 5.295 % à 8.018 %. Les surcoûts effectifs deviennent plus importants avec P.','效率从 94.97% 降到 80.61%，e 从 5.295% 增至 8.018%，表明随 P 增大，有效额外成本的影响上升。')+b('Le code peut être inchangé : e n\'est pas une mesure directe de sa fraction intrinsèquement séquentielle. Communications, synchronisation et déséquilibre sont des causes à examiner.','代码本身可以未变；e 不是固有串行代码比例的直接测量。通信、同步和负载不均衡是需要进一步检查的原因。')
 body+=item(label,key,src,a)
document('03_Karp_Flatt与扩展性','Karp Flatt et passage à l échelle Karp Flatt 与扩展性',b('Partir des temps mesurés pour séparer vitesse, efficacité et fraction séquentielle effective.','从实测时间出发，区分加速比、效率与有效串行比例。'),body)
