x=R['td3ex2_II'];a=eq(r'q=(80,500,420)/1000=(0.08,0.50,0.42),\quad p=0.3q=(0.024,0.15,0.126).')+eq(r'\lambda_i=(1100,26.4,165,138.6),\quad\mu_i=(10000,166.666667,250,120.048019).')+"![CPU et disques différents CPU 与异构磁盘](../../TD/Images/TD3_2627_ex2_partII_network.png)\n\n"+table(['Nœud 节点',r'$\rho_i$','État 状态'],[[n,f'{u:.6f}','Stable 稳定' if u<1 else 'Instable 不稳定'] for n,u in zip(['CPU','D1','D2','D3'],x['rho'])])+b('Q2–3. Le disque 3 reçoit 138.6 instr/s mais ne sert que 120.048 instr/s : le réseau est instable. Il n\'existe pas de W ni de R globaux stationnaires finis.','第 2–3 问：磁盘 3 到达率 138.6，高于服务率 120.048，网络不稳定，没有有限的全局稳态平均等待时间或响应时间。')+eq(r'W_{sans\ I/O}=0.0123596\ {\rm ms},\qquad R_{sans\ I/O}=0.1123596\ {\rm ms}.')+b('Ces valeurs restent valables pour la classe sans I/O, qui ne dépend que du CPU stable. La classe I/O emprunte D3 avec probabilité 0.42 ; ses moyennes stationnaires ne sont pas finies. La partie I est donc préférable à λ=1100.','无 I/O 类只经过稳定的 CPU，上述平均值仍成立；I/O 类以概率 0.42 经过 D3，因此其稳态平均时间不有限。λ=1100 时第一部分配置更好。')
