x=R['exam2025_initial'];x1=R['exam2025_upgrade1'];x2=R['exam2025_upgrade2'];a=eq(r'Q1:\quad v=(1,0.3,0.7+0.3\times0.8,0.3\times0.8)=(1,0.3,0.94,0.24).')+"![Réseau 2025 网络路由图](sources/network2025.png)\n\n"+eq(r'Q2:\quad\lambda<\min(400,180/0.3,550/0.94,125/0.24)=400.')+b('Q3. Pour λ=320, toutes les utilisations sont inférieures à 1.','第 3 问：λ=320 时所有站点利用率小于 1，系统稳定。')+qtable(x,['R1','R2','R3','R4'])+b('Q4. Pour identifier l\'origine de l\'attente du système, comparer les contributions $v_iw_i$.','第 4 问：判断整个系统等待的主要来源，应比较 $v_iw_i$。')+table(['Nœud 节点',r'$v_i$','$v_iw_i$ (ms)','$v_is_i$ (ms)'],[[n,v,f'{w:.6f}',f'{s:.6f}'] for n,v,w,s in zip(['R1','R2','R3','R4'],[1,.3,.94,.24],x['W_contributions'],x['S_contributions'])])+eq(r'W_0=17.026995\ {\rm ms},\quad S_0=7.795758\ {\rm ms},\quad R_0=24.822752\ {\rm ms}.')+b('R1 contribue le plus à W, avec 10 ms par tâche externe. R4 a le plus grand w local, mais seules 24 % des tâches le visitent.','R1 对全局 W 的贡献最大，为每个外部任务 10 ms。R4 的单站等待最长，但只有 24% 的任务访问它。')+b('Q5. Doubler μ1 à 800 ; les arrivées ne changent pas. Le réseau reste stable, avec λ<520.833333.','第 5 问：将 μ1 翻倍至 800，到达率不变；网络仍稳定，新的稳定条件为 λ<520.833333。')+eq(r'w_{1,new}=\frac{320}{800(800-320)}=0.833333\ {\rm ms},\quad W_1=7.860328\ {\rm ms}.')+b('Q6. Après ce remplacement, comparer les contributions au service moyen, $v_is_i$.','第 6 问：第一次更换后，比较各站对平均服务的贡献 $v_is_i$。')+table(['Nœud 节点','$v_is_i$ après Q5 (ms)'],[[n,f'{s:.6f}'] for n,s in zip(['R1','R2','R3','R4'],x1['S_contributions'])])+eq(r'S_1=6.545758\ {\rm ms}.')+b('La contribution dominante est R4, soit 1.92 ms par tâche externe.','R4 的服务贡献最大，为每个外部任务 1.92 ms。')+eq(r'Q7:\quad\mu_{4,new}=3\times125=375,\quad S_2=5.265758\ {\rm ms}.')+eq(r'Q8:\quad W_2=4.965904\ {\rm ms},\quad R_2=W_2+S_2=10.231662\ {\rm ms},\quad A=R_0/R_2=2.426072.')+eq(r'Q9:\quad C_2=1.75C_0,\quad\frac{(Perf/C)_2}{(Perf/C)_0}=\frac{2.426072}{1.75}=1.386327.')+b('Avec la performance définie par l\'inverse du temps de réponse à charge fixée, le rapport performance/prix augmente de 38.63 % : l\'investissement est favorable selon ce critère.','若在固定负载下以响应时间的倒数定义性能，性能/价格提高 38.63%，按此指标投资有效。')
